import numpy as np
from rdkit import Chem
from rdkit.Chem import AllChem
from scipy.optimize import least_squares
s='[O-][C@](c1ccccc1)(C(F)(F)F)c1ccccc1-c1ccc(-c2ccccc2[C@]([O-])(c3ccccc3)C(F)(F)F)cc1'
mp=[
{0:(165,161),1:(132,134),8:(102,102),12:(88,152),13:(59,126),14:(17,139),15:(14,177),16:(47,205),17:(82,194),18:(106,225),19:(137,226),20:(169,262),21:(168,295),40:(138,293),41:(106,258),22:(198,327),23:(185,359),24:(202,389),25:(242,391),26:(264,355),27:(240,325),28:(260,287),29:(248,248),2:(132,93),30:(301,288),36:(292,318)},
{0:(255,151),1:(245,115),8:(217,86),12:(264,74),13:(241,42),14:(255,15),15:(292,15),16:(315,46),17:(303,76),18:(331,108),19:(361,111),20:(393,145),21:(392,178),40:(361,177),41:(329,146),22:(416,210),23:(452,201),24:(480,230),25:(469,270),26:(445,273),27:(413,245),28:(368,260),29:(334,246),2:(205,115),30:(370,305),36:(399,283)}]

def unit(x):
    return np.asarray(x)/np.linalg.norm(x)
def mk(mnum):
  pos=mp[mnum]
  mol=Chem.AddHs(Chem.MolFromSmiles(s))
  c=Chem.Conformer(mol.GetNumAtoms()); xyz={}
  def transform(pt,z=0):return np.array([(pt[0]-249)*.039,(201-pt[1])*.039,z])
  for i,p in pos.items():xyz[i]=transform(p,(-.77 if i in (2,30) else .72 if i in (8,36) else 0.))
  # give middle aromatic rings a realistic noncoplanar tilt
  for i,z in [(18,0),(19,.45),(20,.65),(21,.25),(40,-.25),(41,-.3)]:xyz[i][2]=z*(1 if mnum==0 else -1)
  # complete pendant phenyl rings (benzene ipso at 2 or 30)
  for stereo,ipso in [(1,2),(28,30)]:
    direction=xyz[ipso]-xyz[stereo];direction[2]=0
    direction=unit(direction)
    side=np.array([-direction[1],direction[0],0.]);
    # regular benzene with 1.40 A bonds
    for j in range(1,6):
      a=j*np.pi/3
      xyz[ipso+j]=xyz[ipso]+1.40*(np.sin(a)*side+(1-np.cos(a))*direction)
  # fluorines on both CF3 groups, with rotation chosen for noncrowded placement
  for stereo,cf in [(1,8),(28,36)]:
    ax=unit(xyz[cf]-xyz[stereo]);ref=np.array([0.,0.,1.])
    if abs(np.dot(ax,ref))>.9:ref=np.array([0.,1.,0.])
    perp=unit(np.cross(ax,ref));perp2=np.cross(ax,perp)
    for j in range(3):
      angle=(j*2*np.pi/3+0.3+(mnum*.4))
      xyz[cf+1+j]=xyz[cf]+1.34*(ax/3+np.sqrt(8)/3*(np.cos(angle)*perp+np.sin(angle)*perp2))
  # Place explicit hydrogen atoms radially from center of ring
  for atom in mol.GetAtoms():
    i=atom.GetIdx()
    if i in xyz:continue
    if atom.GetSymbol()!='H':raise ValueError((i,atom.GetSymbol()))
    parent=atom.GetNeighbors()[0].GetIdx(); nbs=[n.GetIdx() for n in mol.GetAtomWithIdx(parent).GetNeighbors() if n.GetIdx()!=i]
    v=unit(sum((xyz[parent]-xyz[n] for n in nbs),np.zeros(3)))
    xyz[i]=xyz[parent]+1.083*v
  for i in range(mol.GetNumAtoms()): c.SetAtomPosition(i,xyz[i])
  mol.RemoveAllConformers();mol.AddConformer(c)
  prop=AllChem.MMFFGetMoleculeProperties(mol)
  print('MMFF',mnum, bool(prop),'atoms',mol.GetNumAtoms(),flush=True)
  if prop:
    for displacement,weight,iterations in [(0.12,80,350),(.55,12,500)]:
      ff=AllChem.MMFFGetMoleculeForceField(mol,prop,ignoreInterfragInteractions=False)
      for i in list(pos):
        if i in (2,8,30,36): ff.MMFFAddPositionConstraint(i,displacement+.2,weight*.5)
        else: ff.MMFFAddPositionConstraint(i,displacement,weight)
      ff.Initialize()
      print('init energy',ff.CalcEnergy(),flush=True)
      print('iter',ff.Minimize(maxIts=iterations),'end',ff.CalcEnergy(),flush=True)
      conform=mol.GetConformer()
      for i,coord in enumerate(ff.Positions().reshape(-1,3)):conform.SetAtomPosition(i,coord)
  return mol

mols=[mk(0),mk(1)]
# Cartesian fit optimized bridge, terminal ligand oxygens, and metal placement together
coords=np.array([[*a] for mol in mols for a in mol.GetConformer().GetPositions()]);nn=mols[0].GetNumAtoms();
# oxygen indices 0 terminal left,29 lower bridge, nn+0 upper bridge, nn+29 terminal right
# use 2 chromium points optimized jointly to oxygens, while minimize oxy deviations from optimized ligand structure
ox=np.array([0,29,nn,nn+29]);
metal=np.array([[-1.65,0.,0.],[1.65,0.,0.]])
o0=coords[ox].copy();
# permit O positional movement at most 0.6 A; preferred Cr-O lengths 2.03 to 2.13A
pairs=[(0,0),(0,1),(1,1),(1,2),(0,2),(1,3)] # metal,o index 0 term left,1 low bridge,2 upper bridge,3 term right
# Actually right Cr doesn't bond bottom bridge? yes, right Cr bonded low bridge and upper bridge

def residual(v):
    os=v[:12].reshape(4,3); metals=v[12:].reshape(2,3)
    res=[]
    for met,oi in pairs:res.append((np.linalg.norm(metals[met]-os[oi])-2.06)*8)
    for k in range(4):
       parent=coords[[1,28,nn+1,nn+28][k]]
       res.append((np.linalg.norm(os[k]-parent)-1.42)*10)
       res.extend((os[k]-o0[k])*[3.5 if k in (0,3) else 4.5]*3)
    res.append((np.linalg.norm(metals[0]-metals[1])-3.0)*2)
    res.extend((metals.flatten()-metal.flatten())*1.5)
    return res
opt=least_squares(residual,np.r_[o0.flatten(),metal.flatten()],max_nfev=1000)
coords[ox]=opt.x[:12].reshape(4,3);metals=opt.x[12:].reshape(2,3)
for mt,oi in pairs:print('Cr-O',mt,oi,np.linalg.norm(metals[mt]-coords[ox[oi]]))
print('Cr Cr',np.linalg.norm(metals[0]-metals[1]))
elems=[a.GetSymbol() for mol in mols for a in mol.GetAtoms()]+['Cr','Cr']
coords=np.vstack((coords,metals))
with open('answer.xyz','w') as f:
    f.write(f'{len(elems)}\nDichromium(II) four alkoxide terphenyl complex; total spin S=4\n')
    for el,v in zip(elems,coords): f.write('%s % .7f % .7f % .7f\n'%(el,*v))
print('answer.xyz',len(elems),flush=True)
